[{"order":1,"type":"heading","text":"Module Sources & Registry Management in Terraform"},{"order":2,"type":"paragraph","text":"Terraform modules are containers for multiple resources that are used together. Registry management and understanding module sources allow you to reuse infrastructure code efficiently across your organization."},{"order":3,"type":"subheading","text":"Understanding Module Sources"},{"order":4,"type":"paragraph","text":"The source argument in a module block tells Terraform where to find the source code for the requested module. Terraform supports several different types of source destinations."},{"order":5,"type":"bullet_point","text":"Local paths: Reference modules stored on your local disk using relative paths starting with ./ or ../."},{"order":6,"type":"bullet_point","text":"Standard Terraform Registry: Reference public or private modules directly from the Terraform Registry using the namespace/name/provider format."},{"order":7,"type":"bullet_point","text":"Git and Mercurial repositories: Download modules directly from Git repositories by specifying the repository URL and optional subdirectories."},{"order":8,"type":"bullet_point","text":"HTTP URLs and S3 buckets: Download archives directly from direct HTTP/HTTPS links or compatible cloud storage systems."},{"order":9,"type":"subheading","text":"Using the Terraform Registry"},{"order":10,"type":"paragraph","text":"The public Terraform Registry is the primary repository for community-contributed and official Terraform modules. You can reference them easily by declaring the source attribute with the module's address."},{"order":11,"type":"code","text":"module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "3.18.0"

  name = "my-vpc"
  cidr = "10.0.0.0/16"
}"},{"order":12,"type":"subheading","text":"Working with Git Module Sources"},{"order":13,"type":"paragraph","text":"When building internal modules, organizations often store them in private Git repositories. Terraform can clone these repositories directly, supporting specific branches, tags, or commits using query parameters."},{"order":14,"type":"code","text":"module "app_server" {
  source = "git::https://github.com/example/terraform-aws-app-server.git?ref=v1.2.0"

  instance_type = "t3.micro"
}"},{"order":15,"type":"subheading","text":"Private Registries and Authentication"},{"order":16,"type":"paragraph","text":"Enterprise environments use private registries (such as Terraform Cloud or GitHub Packages) to share verified modules internally. To authenticate with a private registry, you must configure credentials in your local CLI configuration file, typically located at ~/.terraformrc."},{"order":17,"type":"code","text":"credentials "app.terraform.io" {
  token = "your-api-token-here"
}"},{"order":18,"type":"subheading","text":"Best Practices for Registry Management"},{"order":19,"type":"bullet_point","text":"Always pin module versions to avoid unexpected breaking changes when running terraform init or terraform apply."},{"order":20,"type":"bullet_point","text":"Leverage private registries for enterprise governance, ensuring all teams consume compliance-checked infrastructure modules."}]
